import{_ as e}from"./plugin-vue_export-helper-c27b6911.js";import{o as d,c as o,e as t}from"./app-f7ddf95e.js";const c={},a=t(`<h1 id="btop-现代化终端资源监控器-cpu-内存-网络-磁盘" tabindex="-1"><a class="header-anchor" href="#btop-现代化终端资源监控器-cpu-内存-网络-磁盘" aria-hidden="true">#</a> btop（现代化终端资源监控器（CPU/内存/网络/磁盘））</h1><blockquote><p>Homebrew 版本 1.4.5 ｜ 主页：见官方文档 ｜ 安装：<code>brew install btop</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>btop 是一款用 C++ 编写的现代化终端资源监控器，对标经典 htop，用实时曲线、柱状图和彩色界面直观展示 CPU、内存、网络和磁盘的使用情况。它解决了传统 top 命令信息冗长、不直观的问题，让你在一个界面里就能看清整台机器的运行状态，特别适合服务器运维、性能排查和日常压测时观察资源占用。</p><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装</span>
brew <span class="token function">install</span> btop

<span class="token comment"># 升级（先更新 Homebrew 索引）</span>
brew update <span class="token operator">&amp;&amp;</span> brew upgrade btop

<span class="token comment"># 卸载</span>
brew uninstall btop

<span class="token comment"># 验证安装成功（查看版本号）</span>
btop <span class="token parameter variable">--version</span>
<span class="token comment"># 输出示例：btop v1.4.5</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>安装完成后直接输入 <code>btop</code> 即可进入实时监控界面，按 <code>q</code> 或 <code>Esc</code> 退出。</p><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><p>btop 主要通过交互式界面内的按键操作，也有少量命令行参数：</p><table><thead><tr><th>命令 / 按键</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>btop</code></td><td>启动监控界面</td><td><code>btop</code></td></tr><tr><td><code>btop -p 1,2,3</code></td><td>指定预设布局（1/2/3），显示不同模块组合</td><td><code>btop -p 1</code></td></tr><tr><td><code>btop -t</code></td><td>启用强制 256 色模式（配合终端的真彩模式）</td><td><code>btop -t</code></td></tr><tr><td><code>btop -v</code></td><td>输出版本号</td><td><code>btop -v</code></td></tr><tr><td><code>-r &lt;ms&gt;</code></td><td>设置刷新间隔（毫秒，默认 1500）</td><td><code>btop -r 500</code></td></tr><tr><td><code>-d</code></td><td>直接显示磁盘 IO 模块</td><td><code>btop -d</code></td></tr><tr><td><code>m</code></td><td>切换内存 / 交换分区显示</td><td><code>btop</code> 内按 <code>m</code></td></tr><tr><td><code>n</code></td><td>切换网络总览 / 进程显示</td><td><code>btop</code> 内按 <code>n</code></td></tr><tr><td><code>p</code></td><td>在预设布局间循环切换</td><td><code>btop</code> 内按 <code>p</code></td></tr><tr><td><code>?</code> 或 <code>h</code></td><td>打开按键帮助</td><td><code>btop</code> 内按 <code>?</code></td></tr></tbody></table><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-启动并查看整体资源占用" tabindex="-1"><a class="header-anchor" href="#示例-1-启动并查看整体资源占用" aria-hidden="true">#</a> 示例 1：启动并查看整体资源占用</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 直接进入默认监控界面</span>
btop
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>界面顶部是 CPU 和内存曲线，中部是进程列表（按 CPU 占用排序）。观察要点：</p><ul><li>数字块颜色：绿色表示负载低，黄色表示中，红色表示高。</li><li>按 <code>↑</code>/<code>↓</code> 在进程间移动，按 <code>Enter</code> 或 <code>o</code> 查看该进程的详细信息（PID、线程、打开的文件等）。</li><li>按 <code>k</code> 直接结束选中的进程（会先要求确认）。</li></ul><h3 id="示例-2-快速定位高-cpu-进程并排序" tabindex="-1"><a class="header-anchor" href="#示例-2-快速定位高-cpu-进程并排序" aria-hidden="true">#</a> 示例 2：快速定位高 CPU 进程并排序</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 以 500ms 刷新、第一套布局启动，便于观察瞬时峰值</span>
btop <span class="token parameter variable">-r</span> <span class="token number">500</span> <span class="token parameter variable">-p</span> <span class="token number">1</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>进入界面后，在进程区反复按 <code>P</code>（大写，CPU 排序）可以切换排序方向，找出占用最高的进程；按 <code>M</code> 按内存排序，排查内存泄漏。定位到可疑进程后按 <code>Enter</code> 查看其 PID，再配合 <code>kill &lt;PID&gt;</code> 在另一个终端里处理。</p><h3 id="示例-3-监控网络流量与磁盘-io" tabindex="-1"><a class="header-anchor" href="#示例-3-监控网络流量与磁盘-io" aria-hidden="true">#</a> 示例 3：监控网络流量与磁盘 IO</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 直接打开网络模块</span>
btop <span class="token parameter variable">-d</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>在界面内按 <code>n</code> 循环切换网络总览和网络进程视图，查看实时上传 / 下载速率（默认单位 bytes，可在设置中改成 bits）。按 <code>↑</code>/<code>↓</code> 或鼠标滚轮选择某个网卡，下方曲线会显示该网卡的实时吞吐。磁盘模块同理，能看到各分区读写速度和 IO 等待时间。</p><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><ol><li><p><strong>配置文件位置</strong>：btop 的配置文件位于 <code>~/.config/btop/btop.conf</code>（首次运行后自动生成）。常用可调项：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 用编辑器打开配置</span>
<span class="token function">vim</span> ~/.config/btop/btop.conf
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>可修改 <code>color_theme</code>（主题，如 <code>dracula</code>、<code>monokai</code>）、<code>update_ms</code>（刷新间隔）、<code>shown_boxes</code>（默认显示的模块）等。改完按 <code>Esc</code> 后在界面内按 <code>Esc</code> 再按 <code>q</code> 重启即可生效。</p></li><li><p><strong>主题与配色</strong>：内置多种主题，可在界面内按 <code>Esc</code> 打开主菜单 → <code>Options</code> → <code>Color theme</code> 切换，也可在配置里直接写 <code>color_theme = &quot;dracula&quot;</code>。</p></li><li><p><strong>与其它工具搭配</strong>：</p><ul><li>用 <code>watch -n 1 btop -r 1000</code> 以固定节奏刷新观察；</li><li>结合 <code>htop</code> / <code>top</code> 做交叉对比；</li><li>配合 SSH 远程登录服务器后运行，实时查看远端机器负载（注意网络延迟，可把刷新间隔调大，如 <code>btop -r 3000</code>）。</li></ul></li><li><p><strong>环境变量</strong>：<code>COLORTERM=truecolor</code> 可让 btop 使用真彩（24-bit）配色，界面更鲜艳；若终端支持 256 色但配色发灰，可加 <code>-t</code> 强制 256 色。</p></li></ol><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><ol><li><p><strong>终端兼容性</strong>：btop 需要较新的终端（如 iTerm2、kitty、Windows Terminal、支持真彩的 xterm），老终端可能出现乱码或颜色异常。遇到花屏先尝试 <code>btop -t</code>，或升级终端。</p></li><li><p><strong>按键与中文输入法冲突</strong>：在中文输入法开启时，快捷键（如 <code>q</code>、<code>p</code>）可能无法触发。按 <code>Ctrl+Space</code> 或 <code>Ctrl+</code> 切换到英文输入法再操作。</p></li><li><p><strong>进程列表为空或乱序</strong>：macOS 上若权限不足，部分进程信息可能不完整。建议通过 sudo 或确保当前用户权限正常；磁盘模块在某些容器 / 虚拟化环境可能显示不出 IO。</p></li><li><p><strong>刷新太频繁导致高 CPU 占用</strong>：<code>-r</code> 设太小的值（如 200ms）会让 btop 自身消耗较多资源，干扰观察结果。日常用默认 1500ms 即可，排查瞬时峰值再临时调小。</p></li><li><p><strong>退出方式</strong>：直接按 <code>q</code> 或 <code>Esc</code> 退出；若界面卡住，可先按 <code>Ctrl+C</code> 再按 <code>q</code> 兜底，正常不会留下残留进程。</p></li></ol>`,25),n=[a];function s(i,r){return d(),o("div",null,n)}const b=e(c,[["render",s],["__file","btop.html.vue"]]);export{b as default};
